evidence:
supabase.rpc('auto_link_customer_request_products_v2', {
        p_apply: true,
        p_branch: branch === 'all' ? null : branch,
      })

supabase.rpc('import_customer_service_queue_results_v4', {
        p_actor_id: user.id,
        p_branch: managerView ? 'كل الفروع' : userBranch,
        p_file_name: preview.fileName,
        p_rows: safeRows,
      })

supabase.rpc('import_customer_followup_results_v1', {
        p_actor_id: user.id,
        p_branch: branch,
        p_file_name: fileName,
        p_rows: rows,
      })

supabase.rpc('penalize_followup_fraud', {
        p_followup_id: followupId,
        p_flagged_by: user?.name || 'مدير',
        p_reason: reason.trim(),
      })

supabase.rpc('advance_customer_request_v2', {
    p_request_id: request.id,
    p_action: action,
    p_notes: notes?.trim() || null,
    p_expected_arrival_date: expectedArrivalDate || null,
  })

supabase.rpc('record_customer_request_contact_v2', {
    p_request_id: request.id,
    p_outcome: input.outcome,
    p_notes: input.notes?.trim() || null,
    p_followup_at: input.outcome === 'later' ? input.followupAt || null : null,
  })

supabase.rpc('move_customer_request_to_shortage_v1', {
    p_request_id: request.id,
  })

supabase.rpc('repair_customer_request_customer_v2', {
    p_request_id: requestId,
    p_customer_id: customer.id,
    p_keep_request_branch: keepRequestBranch,
  })

supabase.rpc('apply_customer_request_staff_attribution_v1', {
    p_source_label: input.sourceLabel,
    p_branch: input.branch,
    p_staff_id: input.staffId,
    p_confirm: 'APPLY_CONFIRMED_MAPPING',
  })

supabase.rpc('dawaa_archive_customer_followup_v1', {
    p_followup_id: followupId,
    p_reason: reason.trim(),
    p_actor: null,
  })

supabase.rpc('dawaa_restore_customer_followup_v1', {
    p_followup_id: followupId,
    p_actor: null,
  })

supabase.rpc('dawaa_postpone_customer_followup_v1', {
    p_followup_id: followupId,
    p_postponed_until: postponedUntil,
    p_actor: null,
  })

supabase.rpc('dawaa_cancel_customer_followup_v1', {
    p_followup_id: followupId,
    p_reason: reason.trim(),
    p_actor_id: null,
    p_actor_name: null,
  })

supabase.rpc('dawaa_create_customer_followup_request_v1', {
    p_payload: requestPayload as any,
  })

supabase.rpc('link_customer_request_product', {
    p_request_id: requestId,
    p_product_id: productId,
  })

service
      .from('whatsapp_conversation_actions')
      .update({
        payload: { ...existingPayload, delivery_context: deliveryContext },
        updated_at: new Date().toISOString(),
      })

supabase.rpc('return_shortage_to_customer_request_v2', {
      p_shortage_item_id: String(row.id || ''),
      p_notes: `تم توفير الصنف من النواقص: ${String(row.item_name || row.title || 'الصنف')}`,
    })

updateSafe('conversation_sales_reviews', managerReviewTarget.id, {
          manager_review_score: score,
          manager_review_notes: managerForm.notes,
          manager_reviewed_by: user?.name || 'مدير عام',
          manager_reviewed_at: new Date().toISOString(),
        })
